(()=>{
'use strict';

const Rush=window.__RUSH_MODULES||{};
const Board=Rush.Board,SHAPES=Rush.SHAPES||[],ROTATIONS=Rush.ROTATIONS||[];
const simulatePlacement=Rush.simulatePlacement,boardFeatures=Rush.boardFeatures;
const COLS=Rush.COLS||10,ROWS=Rush.ROWS||20;
if(!Board||SHAPES.length!==7||!ROTATIONS.length||typeof simulatePlacement!=='function')return;

const NATIVE_PUSH=Array.prototype.push;
const NATIVE_SHIFT=Array.prototype.shift;
const originalLock=Board.prototype.lock;
const QUEUE_MARK=Symbol('customForecastQueueV30');

// The solver evaluates the complete queue already generated by Custom Mode and
// then forecasts enough new tetrominoes to reach a ten-placement horizon.
const TOTAL_LOOKAHEAD=10;
const MAX_EXISTING_QUEUE=5;
const MAX_FIXED_BEAM=64;
const MAX_FUTURE_BEAM=150;
const MAX_PLACEMENTS_PER_SHAPE=12;
const SEARCH_BUDGET_MS=180;

let activeBoard=null;
let queueRef=null;
let lastShiftedShape=null;
let pendingActivation=false;
let forecast=[];
let forecastExact=false;
let forecastStarted=false;
let lastPlan=null;

const isShape=value=>Number.isInteger(value)&&value>=0&&value<SHAPES.length;
const isShapeArray=array=>Array.isArray(array)&&array.every(isShape);
const cloneGrid=grid=>grid.map(row=>row.slice());
const gridKey=grid=>grid.map(row=>row.map(cell=>cell?'1':'0').join('')).join('');
const countBlocks=grid=>grid.reduce((total,row)=>total+row.reduce((sum,cell)=>sum+(cell?1:0),0),0);
const boardEmpty=grid=>!grid.some(row=>row.some(Boolean));

function bottomThreeRowsOnly(grid){
  if(!Array.isArray(grid)||grid.length!==ROWS)return false;
  let blocks=0;
  for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(grid[y][x]){
    blocks++;
    if(y<ROWS-3)return false;
  }
  return blocks>0;
}

// Remove all visual traces from the previous forecast version. The solver now
// runs silently and leaves the objective, queue panel and side rail unchanged.
function removeForecastUi(){
  document.getElementById('customAssistStatus')?.remove();
  document.getElementById('custom-final-assist-v27-style')?.remove();
  document.getElementById('custom-final-assist-v29-style')?.remove();
  const panel=document.querySelector('#customPlayScreen .custom-next-panel');
  panel?.classList.remove('forecast-active','assist-active');
  const label=panel?.querySelector(':scope > span');
  if(label)label.textContent='NEXT';
  const objective=document.querySelector('#customPlayScreen .custom-objective b');
  if(objective)objective.textContent='EMPTY THE BOARD';
}

function placementScore(candidate){
  if(boardEmpty(candidate.grid))return 10_000_000;
  const blocks=countBlocks(candidate.grid);
  const features=typeof boardFeatures==='function'?boardFeatures(candidate.grid):{
    holes:0,holeDepth:0,blocksAboveHoles:0,aggregateHeight:0,maxHeight:0,
    bumpiness:0,rowTransitions:0,columnTransitions:0,cumulativeWells:0
  };
  let score=0;
  score+=candidate.lines*520;
  score+=candidate.erodedPieceCells*32;
  score-=blocks*28;
  score-=features.holes*210;
  score-=features.holeDepth*23;
  score-=features.blocksAboveHoles*44;
  score-=features.aggregateHeight*5.2;
  score-=features.maxHeight*18;
  score-=features.bumpiness*6.5;
  score-=features.rowTransitions*2.4;
  score-=features.columnTransitions*3.2;
  score-=features.cumulativeWells*4.5;
  if(candidate.topped)score-=10_000_000;
  return score;
}

function placementsFor(grid,shapeIndex){
  const unique=new Map();
  for(const rotation of ROTATIONS[shapeIndex]||[]){
    for(let x=-3;x<COLS;x++){
      const candidate=simulatePlacement(grid,shapeIndex,rotation,x);
      if(!candidate||candidate.topped)continue;
      const key=gridKey(candidate.grid);
      const scored={
        grid:candidate.grid,shape:shapeIndex,x:candidate.x,y:candidate.y,
        rot:candidate.rot,lines:candidate.lines,score:placementScore(candidate)
      };
      const previous=unique.get(key);
      if(!previous||scored.score>previous.score)unique.set(key,scored);
    }
  }
  return [...unique.values()].sort((a,b)=>b.score-a.score);
}

function trimStates(states,limit){
  const unique=new Map();
  for(const state of states){
    const key=gridKey(state.grid);
    const previous=unique.get(key);
    if(!previous||state.score>previous.score)unique.set(key,state);
  }
  return [...unique.values()].sort((a,b)=>b.score-a.score).slice(0,limit);
}

function expandKnownQueue(startStates,knownQueue,startedAt){
  let states=startStates;
  for(let index=0;index<knownQueue.length;index++){
    const shape=knownQueue[index],expanded=[];
    for(const state of states){
      for(const placement of placementsFor(state.grid,shape).slice(0,MAX_PLACEMENTS_PER_SHAPE)){
        const next={
          grid:placement.grid,
          score:state.score+placement.score,
          added:state.added.slice(),
          path:state.path.concat([{shape,...placement}])
        };
        if(boardEmpty(next.grid))return {solved:next,states:[next],consumed:index+1};
        expanded.push(next);
      }
      if(performance.now()-startedAt>SEARCH_BUDGET_MS)break;
    }
    if(!expanded.length)return {solved:null,states:[],consumed:index+1};
    states=trimStates(expanded,MAX_FIXED_BEAM);
    if(performance.now()-startedAt>SEARCH_BUDGET_MS)break;
  }
  return {solved:null,states,consumed:knownQueue.length};
}

function planForecast(grid,currentQueue){
  const startedAt=performance.now();
  const knownQueue=currentQueue.filter(isShape).slice(0,MAX_EXISTING_QUEUE);
  const futureDepth=Math.max(0,TOTAL_LOOKAHEAD-knownQueue.length);
  const initial={grid:cloneGrid(grid),score:0,added:[],path:[]};
  const known=expandKnownQueue([initial],knownQueue,startedAt);

  if(known.solved){
    return {pieces:[],exact:true,path:known.solved.path,knownQueue,lookahead:knownQueue.length,elapsed:performance.now()-startedAt};
  }

  let states=known.states.length?known.states:[initial];
  let best=states[0]||initial;

  for(let depth=1;depth<=futureDepth;depth++){
    const expanded=[];
    for(const state of states){
      for(let shape=0;shape<SHAPES.length;shape++){
        const options=placementsFor(state.grid,shape).slice(0,MAX_PLACEMENTS_PER_SHAPE);
        for(const placement of options){
          const next={
            grid:placement.grid,
            score:state.score+placement.score,
            added:state.added.concat(shape),
            path:state.path.concat([{shape,...placement}])
          };
          if(boardEmpty(next.grid)){
            return {
              pieces:next.added,
              exact:true,
              path:next.path,
              knownQueue,
              lookahead:knownQueue.length+next.added.length,
              elapsed:performance.now()-startedAt
            };
          }
          expanded.push(next);
          if(!best||next.score>best.score)best=next;
        }
        if(performance.now()-startedAt>SEARCH_BUDGET_MS)break;
      }
      if(performance.now()-startedAt>SEARCH_BUDGET_MS)break;
    }
    if(!expanded.length||performance.now()-startedAt>SEARCH_BUDGET_MS)break;
    states=trimStates(expanded,MAX_FUTURE_BEAM);
    if(states[0]&&(!best||states[0].score>best.score))best=states[0];
  }

  let helpful=best?.added?.slice()||[];
  if(!helpful.length){
    let bestShape=0,bestScore=-Infinity;
    for(let shape=0;shape<SHAPES.length;shape++){
      const option=placementsFor(grid,shape)[0];
      if(option&&option.score>bestScore){bestScore=option.score;bestShape=shape;}
    }
    helpful=[bestShape];
  }
  while(helpful.length<Math.max(1,futureDepth))helpful.push(helpful[helpful.length-1]);

  return {
    pieces:helpful.slice(0,Math.max(1,futureDepth)),
    exact:false,
    path:best?.path||[],
    knownQueue,
    lookahead:TOTAL_LOOKAHEAD,
    elapsed:performance.now()-startedAt
  };
}

function clearPlan(){
  pendingActivation=false;
  forecast=[];
  forecastStarted=false;
  forecastExact=false;
  lastPlan=null;
}

function applyPlan(plan){
  lastPlan=plan;
  forecast=plan.pieces.slice();
  forecastExact=plan.exact;
  forecastStarted=true;
}

function replanFromCurrentQueue(){
  if(!activeBoard||!bottomThreeRowsOnly(activeBoard.grid)){
    clearPlan();
    return;
  }
  if(!queueRef||!isShapeArray(queueRef)){
    pendingActivation=true;
    return;
  }
  pendingActivation=false;
  applyPlan(planForecast(activeBoard.grid,queueRef.slice(0,MAX_EXISTING_QUEUE)));
}

function isLikelyCustomQueue(array){
  return document.body.dataset.screen==='custom-play'&&
    activeBoard&&activeBoard.name==='CUSTOM'&&
    array!==forecast&&array.length>=4&&array.length<=5&&isShapeArray(array);
}

Array.prototype.shift=function(...args){
  if(isLikelyCustomQueue(this)&&this.length===5){
    queueRef=this;
    this[QUEUE_MARK]=true;
    lastShiftedShape=this[0];
  }
  return NATIVE_SHIFT.apply(this,args);
};

Array.prototype.push=function(...items){
  const isQueueAppend=(this[QUEUE_MARK]||isLikelyCustomQueue(this))&&
    this!==forecast&&this.length===4&&items.length===1&&isShape(items[0]);

  if(isQueueAppend){
    queueRef=this;
    this[QUEUE_MARK]=true;

    // The first activation can happen between shift and push. Reconstruct the
    // unchanged queue as the newly active piece plus the four remaining pieces.
    if(pendingActivation&&activeBoard&&bottomThreeRowsOnly(activeBoard.grid)){
      const unchangedQueue=[lastShiftedShape,...this].filter(isShape).slice(0,MAX_EXISTING_QUEUE);
      applyPlan(planForecast(activeBoard.grid,unchangedQueue));
      pendingActivation=false;
    }

    // Only the newly generated tail piece is replaced. Every piece already in
    // the queue remains exactly where it was.
    if(forecast.length){
      items[0]=forecast[0];
      forecast=forecast.slice(1);
      if(lastPlan)lastPlan={...lastPlan,pieces:forecast.slice()};
    }
  }

  return NATIVE_PUSH.apply(this,items);
};

Board.prototype.lock=function(){
  const result=originalLock.call(this);
  if(this.name!=='CUSTOM')return result;

  activeBoard=this;
  if(bottomThreeRowsOnly(this.grid))replanFromCurrentQueue();
  else clearPlan();
  return result;
};

removeForecastUi();
const cleanupObserver=new MutationObserver(removeForecastUi);
cleanupObserver.observe(document.documentElement,{childList:true,subtree:true});

window.__rushDuelFinalAssist={
  plan:(grid,queue)=>planForecast(grid,queue),
  active:()=>forecastStarted,
  exact:()=>forecastExact,
  pending:()=>forecast.slice(),
  queue:()=>queueRef?.slice?.()||[],
  lookahead:()=>TOTAL_LOOKAHEAD,
  bottomThreeRowsOnly
};
})();
